window.products.push({"id":1048455,"name":"Spectrum Diversified Bloom Paper Towel Holder, Satin Nickel","category":"homeandappliances","retail price":31.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/512ETUaL2HL._AC_SL1500_.jpg","description":"Inspired by the blooming of a spring flower, Spectrum's Bloom Paper Towel Holder will add a fresh look to any home. Designed to stylishly store and display your paper towels, this paper towel holder will make a great addition to your kitchen and serve as a surefire conversation starter. Made from durable steel, the sturdy base keeps paper towels off the counter and prevents the unit from tipping while in use. This holder features a convenient blooming design that encircles the roll of paper towels that keeps them from unraveling.","images":["https://m.media-amazon.com/images/I/512ETUaL2HL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Spectrum Diversified","source_asin":"B01K8GY52Y","category_path":"Home & Kitchen"},"sku":"BM-1048455","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01K8GY52Y","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01K8GY52Y","price_pending":true,"merchant_ready":false});
